window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a3a18da95d828fde"]={"versions": [{"id": "FIG-a3a18da95d828fde", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architekturschaubild / Interaktionsübersicht des Synchronized Time-Base Managers (StbM) innerhalb der AUTOSAR Classic Platform. Das Diagramm ordnet den StbM als Vermittlungsinstanz zwischen Zeitbasis-Quellen (Providern) und Zeitbasis-Nutzern (Customer / Consumer) ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist der <code>Synchronized Time-base Manager</code>. Auf der Oberseite sind als <code>&lt;&lt;Customer&gt;&gt;</code> (orange Blöcke) modelliert:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C</code> (Software-Component)</li>\n<li><code>OS</code> (Operating System)</li>\n<li><code>...</code> (weitere optionale Kunden)</li>\n</ul>\n<p class=\"fig-p\">Auf der Unterseite sind als <code>&lt;&lt;Provider&gt;&gt;</code> (graue Blöcke) angebunden:</p>\n<ul class=\"fig-list\">\n<li><code>FlexRay If</code> (FlexRay Interface)</li>\n<li><code>TTCan If</code> (TTCAN Interface)</li>\n<li><code>...</code> (weitere optionale Provider)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen sind durch gerichtete Pfeile repräsentiert:</p>\n<ul class=\"fig-list\">\n<li>Pfeil 1: Durchgezogener Pfeil vom StbM zum Provider (aktiver Aufruf des Providers durch den StbM).</li>\n<li>Pfeil 2: Gestrichelter Pfeil vom Provider zum StbM (Aufruf des StbM durch den Provider / Callback bzw. Notification).</li>\n<li>Pfeil 3: Durchgezogener Pfeil vom StbM zum Customer (StbM ruft Customer auf bzw. benachrichtigt diesen).</li>\n<li>Pfeil 4: Durchgezogener Pfeil vom Customer zum StbM (Customer fragt StbM ab bzw. übergibt Daten).</li>\n<li>Analoge unnummerierte Pfeilverbindungen bestehen zu den übrigen Customer- und Provider-Instanzen (<code>OS</code> verfügt ausschließlich über einen ankommenden Pfeil 3 vom StbM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Kommunikationsmodi bzw. Interaktionsrichtungen je Ebene:</p>\n<ol class=\"fig-list\">\n<li>Provider-Ebene: Der StbM fragt Zeitinformationen aktiv beim Bus-Interface ab (Pfeil 1, Polling/Request) oder wird vom Provider ereignisgesteuert aufgerufen (Pfeil 2, Callback/Interrupt/Notification).</li>\n<li>Customer-Ebene: Zeitinformationen bzw. Synchronisationsereignisse werden aktiv an den Customer signalisiert (Pfeil 3) oder von diesem synchron/asynchron beim StbM abgerufen (Pfeil 4). OS wird beispielhaft rein als Empfänger (Pfeil 3) dargestellt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung definiert das grundlegende Architekturmuster für die Zeitsynchronisation: Der StbM abstrahiert busspezifische Zeitschnittstellen (wie FlexRay oder TTCAN) gegenüber Anwendungssoftware und Betriebssystem. Für Entwickler impliziert dies, dass Hardware- und Busschnittstellen sowohl als aktive Zeitgeber (Push via Callback) als auch als passive Zeitquellen (Pull via API) integrierbar sein müssen, während Konsumenten über vereinheitlichte StbM-Schnittstellen entkoppelt bedient werden.</p>"}, {"id": "FIG-6bfcc388b1b0999a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architekturschaubild / Interaktionsübersicht des Synchronized Time-Base Managers (StbM) innerhalb der AUTOSAR Classic Platform. Das Diagramm ordnet den StbM als Vermittlungsinstanz zwischen Zeitbasis-Quellen (Providern) und Zeitbasis-Nutzern (Customer / Consumer) ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist der <code>Synchronized Time-base Manager</code>. Auf der Oberseite sind als <code>&lt;&lt;Customer&gt;&gt;</code> (orange Blöcke) modelliert:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C</code> (Software-Component)</li>\n<li><code>OS</code> (Operating System)</li>\n<li><code>...</code> (weitere optionale Kunden)</li>\n</ul>\n<p class=\"fig-p\">Auf der Unterseite sind als <code>&lt;&lt;Provider&gt;&gt;</code> (graue Blöcke) angebunden:</p>\n<ul class=\"fig-list\">\n<li><code>FlexRay If</code> (FlexRay Interface)</li>\n<li><code>TTCan If</code> (TTCAN Interface)</li>\n<li><code>...</code> (weitere optionale Provider)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen sind durch gerichtete Pfeile repräsentiert:</p>\n<ul class=\"fig-list\">\n<li>Pfeil 1: Durchgezogener Pfeil vom StbM zum Provider (aktiver Aufruf des Providers durch den StbM).</li>\n<li>Pfeil 2: Gestrichelter Pfeil vom Provider zum StbM (Aufruf des StbM durch den Provider / Callback bzw. Notification).</li>\n<li>Pfeil 3: Durchgezogener Pfeil vom StbM zum Customer (StbM ruft Customer auf bzw. benachrichtigt diesen).</li>\n<li>Pfeil 4: Durchgezogener Pfeil vom Customer zum StbM (Customer fragt StbM ab bzw. übergibt Daten).</li>\n<li>Analoge unnummerierte Pfeilverbindungen bestehen zu den übrigen Customer- und Provider-Instanzen (<code>OS</code> verfügt ausschließlich über einen ankommenden Pfeil 3 vom StbM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Kommunikationsmodi bzw. Interaktionsrichtungen je Ebene:</p>\n<ol class=\"fig-list\">\n<li>Provider-Ebene: Der StbM fragt Zeitinformationen aktiv beim Bus-Interface ab (Pfeil 1, Polling/Request) oder wird vom Provider ereignisgesteuert aufgerufen (Pfeil 2, Callback/Interrupt/Notification).</li>\n<li>Customer-Ebene: Zeitinformationen bzw. Synchronisationsereignisse werden aktiv an den Customer signalisiert (Pfeil 3) oder von diesem synchron/asynchron beim StbM abgerufen (Pfeil 4). OS wird beispielhaft rein als Empfänger (Pfeil 3) dargestellt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung definiert das grundlegende Architekturmuster für die Zeitsynchronisation: Der StbM abstrahiert busspezifische Zeitschnittstellen (wie FlexRay oder TTCAN) gegenüber Anwendungssoftware und Betriebssystem. Für Entwickler impliziert dies, dass Hardware- und Busschnittstellen sowohl als aktive Zeitgeber (Push via Callback) als auch als passive Zeitquellen (Pull via API) integrierbar sein müssen, während Konsumenten über vereinheitlichte StbM-Schnittstellen entkoppelt bedient werden.</p>"}], "trans": [{"from": "FIG-a3a18da95d828fde", "to": "FIG-6bfcc388b1b0999a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
